import React, { useEffect, useRef, useState } from "react";
import axios from "axios";
import { useTheme } from "../component/ThemeContext";

export default function ImgConverter() {
  const { theme, config } = useTheme();
  const isDark = theme === "dark";
  const shellRef = useRef(null);

  const [mode, setMode] = useState("browser");
  const [inputType, setInputType] = useState("image/*");
  const [outputFormat, setOutputFormat] = useState("image/webp");
  const [quality, setQuality] = useState(90);
  const [items, setItems] = useState([]);
  const [message, setMessage] = useState({ type: "", text: "" });
  const [loading, setLoading] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);

  const backendBase = config?.services?.backend_link || "";
  const backendUrl = backendBase ? `${backendBase}/img` : "";

  const colors = isDark
    ? {
        pageBg: "#0f172a",
        cardBg: "#1e293b",
        cardSoft: "#0b1220",
        text: "#f8fafc",
        muted: "#94a3b8",
        border: "#334155",
        accent: "#f59e0b",
      }
    : {
        pageBg: "#f8fafc",
        cardBg: "#ffffff",
        cardSoft: "#f8fafc",
        text: "#0f172a",
        muted: "#64748b",
        border: "#e2e8f0",
        accent: "#d97706",
      };

  const ui = {
    control: {
      background: isDark ? "#0b1220" : "#ffffff",
      color: colors.text,
      borderColor: colors.border,
    },
    buttonGhost: {
      background: "transparent",
      color: colors.text,
      border: `1px solid ${colors.border}`,
    },
    buttonMutedDanger: {
      background: "transparent",
      color: isDark ? "#fca5a5" : "#b91c1c",
      border: `1px solid ${isDark ? "#7f1d1d" : "#fecaca"}`,
    },
    buttonPrimarySoft: {
      background: isDark ? "#1e3a8a" : "#dbeafe",
      color: isDark ? "#bfdbfe" : "#1e3a8a",
      border: `1px solid ${isDark ? "#1d4ed8" : "#93c5fd"}`,
    },
    buttonAccentSoft: {
      background: isDark ? "#78350f" : "#fef3c7",
      color: isDark ? "#fcd34d" : "#92400e",
      border: `1px solid ${isDark ? "#a16207" : "#fcd34d"}`,
    },
    buttonSuccessSoft: {
      background: isDark ? "#052e16" : "#dcfce7",
      color: isDark ? "#86efac" : "#166534",
      border: `1px solid ${isDark ? "#166534" : "#86efac"}`,
    },
  };

  useEffect(() => {
    return () => {
      items.forEach((item) => {
        if (item.previewUrl) URL.revokeObjectURL(item.previewUrl);
        if (item.convertedUrl) URL.revokeObjectURL(item.convertedUrl);
      });
    };
  }, [items]);

  useEffect(() => {
    const onChange = () => setIsFullscreen(Boolean(document.fullscreenElement));
    document.addEventListener("fullscreenchange", onChange);
    return () => document.removeEventListener("fullscreenchange", onChange);
  }, []);

  const onSelectFiles = (event) => {
    const files = Array.from(event.target.files || []);
    if (!files.length) return;

    const validImages = files.filter((file) => {
      if (!file.type.startsWith("image/")) return false;
      if (inputType === "image/*") return true;
      return file.type === inputType;
    });
    if (!validImages.length) {
      setMessage({ type: "danger", text: "Please choose valid image files only." });
      return;
    }

    const newItems = validImages.map((file) => ({
      id: `${file.name}-${file.lastModified}-${Math.random().toString(36).slice(2, 8)}`,
      file,
      name: file.name,
      sizeKB: (file.size / 1024).toFixed(2),
      previewUrl: URL.createObjectURL(file),
      status: "ready",
      convertedUrl: "",
      convertedName: "",
      convertedSizeKB: "",
      error: "",
    }));

    setItems((prev) => [...prev, ...newItems]);
    setMessage({
      type: "success",
      text: `${newItems.length} image(s) added successfully.`,
    });
  };

  const removeItem = (id) => {
    setItems((prev) => {
      const target = prev.find((x) => x.id === id);
      if (target?.previewUrl) URL.revokeObjectURL(target.previewUrl);
      if (target?.convertedUrl) URL.revokeObjectURL(target.convertedUrl);
      return prev.filter((x) => x.id !== id);
    });
  };

  const clearAll = () => {
    items.forEach((item) => {
      if (item.previewUrl) URL.revokeObjectURL(item.previewUrl);
      if (item.convertedUrl) URL.revokeObjectURL(item.convertedUrl);
    });
    setItems([]);
    setMessage({ type: "", text: "" });
  };

  const convertSingleInBrowser = async (item) => {
    const imageElement = await new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error("Failed to load image"));
      img.src = item.previewUrl;
    });

    const canvas = document.createElement("canvas");
    canvas.width = imageElement.width;
    canvas.height = imageElement.height;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(imageElement, 0, 0);

    const blob = await new Promise((resolve) => {
      canvas.toBlob(resolve, outputFormat, quality / 100);
    });

    if (!blob) throw new Error("Conversion failed in browser.");
    return blob;
  };

  const convertSingleInBackend = async (item) => {
    if (!backendUrl) {
      window.alert("Backend not present. Please configure services.backend_link.");
      throw new Error("Backend URL missing.");
    }

    const formData = new FormData();
    formData.append("image", item.file);
    formData.append("format", outputFormat);
    formData.append("quality", String(quality));
    formData.append("action", "convert");

    const response = await axios.post(backendUrl, formData, {
      headers: { "Content-Type": "multipart/form-data" },
      responseType: "blob",
      timeout: 30000,
    });

    return response.data;
  };

  const handleConvertAll = async () => {
    if (!items.length) {
      setMessage({ type: "warning", text: "Please add at least one image." });
      return;
    }

    setLoading(true);
    setMessage({ type: "", text: "" });

    setItems((prev) => prev.map((item) => ({ ...item, status: "processing", error: "" })));

    let successCount = 0;
    let failedCount = 0;

    for (const item of items) {
      try {
        const outputBlob =
          mode === "browser"
            ? await convertSingleInBrowser(item)
            : await convertSingleInBackend(item);

        const ext = outputFormat.split("/")[1] || "png";
        const base = item.name.replace(/\.[^.]+$/, "");
        const convertedName = `${base}-converted.${ext === "jpeg" ? "jpg" : ext}`;
        const convertedUrl = URL.createObjectURL(outputBlob);
        const convertedSizeKB = (outputBlob.size / 1024).toFixed(2);

        setItems((prev) =>
          prev.map((it) =>
            it.id === item.id
              ? {
                  ...it,
                  status: "done",
                  convertedUrl: (() => {
                    if (it.convertedUrl) URL.revokeObjectURL(it.convertedUrl);
                    return convertedUrl;
                  })(),
                  convertedName,
                  convertedSizeKB,
                }
              : it
          )
        );
        successCount += 1;
      } catch (error) {
        const errorText =
          error?.response?.data?.message ||
          error?.message ||
          "Conversion failed for this image.";
        setItems((prev) =>
          prev.map((it) =>
            it.id === item.id
              ? {
                  ...it,
                  status: "error",
                  error: errorText,
                }
              : it
          )
        );
        failedCount += 1;

        const connectionIssue =
          error?.code === "ECONNABORTED" || !error?.response || error?.response?.status >= 500;
        if (mode === "backend" && connectionIssue) {
          window.alert("Backend not present or unreachable. Please start backend and retry.");
        }
      }
    }

    setLoading(false);
    setMessage({
      type: failedCount ? "warning" : "success",
      text: `Conversion completed. Success: ${successCount}, Failed: ${failedCount}.`,
    });
  };

  const downloadAllConverted = () => {
    const ready = items.filter((item) => item.convertedUrl);
    if (!ready.length) {
      setMessage({ type: "warning", text: "No converted files available for download." });
      return;
    }

    ready.forEach((item, index) => {
      setTimeout(() => {
        const a = document.createElement("a");
        a.href = item.convertedUrl;
        a.download = item.convertedName || "converted-image";
        document.body.appendChild(a);
        a.click();
        a.remove();
      }, index * 120);
    });
  };

  const downloadSingle = (item) => {
    if (!item.convertedUrl) return;
    const a = document.createElement("a");
    a.href = item.convertedUrl;
    a.download = item.convertedName || "converted-image";
    document.body.appendChild(a);
    a.click();
    a.remove();
  };

  const toggleFullscreen = async () => {
    if (!shellRef.current) return;
    try {
      if (!document.fullscreenElement) {
        await shellRef.current.requestFullscreen();
      } else {
        await document.exitFullscreen();
      }
    } catch (error) {
      console.warn("Fullscreen failed:", error);
    }
  };

  return (
    <div
      ref={shellRef}
      className="container-fluid py-3"
      style={{ minHeight: "100vh", background: colors.pageBg, color: colors.text }}
    >
      <div className="row justify-content-center">
        <div className="col-12 col-xl-11">
          <div
            className="card border-0 shadow-sm"
            style={{
              background: colors.cardBg,
              borderRadius: 16,
              border: `1px solid ${colors.border}`,
            }}
          >
            <div className="card-body p-3 p-md-4">
              <div className="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3">
                <div>
                  <h4 className="fw-bold mb-1" style={{ color: colors.text }}>
                    <i className="bi bi-arrow-left-right me-2 text-warning"></i>
                    Image Converter
                  </h4>
                </div>
                <div className="d-flex gap-2">
                  <button className="btn btn-sm" style={ui.buttonGhost} onClick={toggleFullscreen}>
                    <i className={`bi ${isFullscreen ? "bi-fullscreen-exit" : "bi-fullscreen"} me-1`}></i>
                    {isFullscreen ? "Exit Fullscreen" : "Fullscreen"}
                  </button>
                  <button className="btn btn-sm" style={ui.buttonMutedDanger} onClick={clearAll}>
                    <i className="bi bi-trash3 me-1"></i>
                    Clear All
                  </button>
                </div>
              </div>

              <div className="row g-2 mb-3">
                <div className="col-12 col-md-6">
                  <label className="form-label fw-semibold mb-1" style={{ color: colors.text }}>Input File Type</label>
                  <select className="form-select" style={ui.control} value={inputType} onChange={(e) => setInputType(e.target.value)}>
                    <option value="image/*">Any Image</option>
                    <option value="image/jpeg">JPG / JPEG</option>
                    <option value="image/png">PNG</option>
                    <option value="image/webp">WEBP</option>
                  </select>
                </div>
                <div className="col-12 col-md-6">
                  <label className="form-label fw-semibold mb-1" style={{ color: colors.text }}>Output File Type</label>
                  <select
                    className="form-select"
                    style={ui.control}
                    value={outputFormat}
                    onChange={(e) => setOutputFormat(e.target.value)}
                  >
                    <option value="image/jpeg">JPG / JPEG</option>
                    <option value="image/png">PNG</option>
                    <option value="image/webp">WEBP</option>
                  </select>
                </div>
              </div>

              {message.text && (
                <div className={`alert alert-${message.type} py-2 mb-3`} role="alert">
                  {message.text}
                </div>
              )}

              <div className="row g-3">
                <div className="col-12 col-lg-6">
                  <div className="p-3 rounded-3 h-100" style={{ background: colors.cardSoft, border: `1px solid ${colors.border}` }}>
                    <div className="d-flex justify-content-between align-items-center mb-3">
                      <h6 className="mb-0 fw-bold" style={{ color: colors.text }} >Input</h6>
                    <small style={{ color: colors.muted }}>Selected: {items.length}</small>
                    </div>
                    <div className="d-flex flex-wrap gap-2 mb-3">
                      <label className="btn fw-semibold mb-0" style={ui.buttonAccentSoft}>
                        <i className="bi bi-upload me-2"></i>Upload
                        <input type="file" hidden multiple accept={inputType} onChange={onSelectFiles} />
                      </label>
                    </div>
                    <div className="row g-2">
                      {items.length === 0 && (
                        <div className="col-12">
                          <div className="text-center py-4" style={{ color: colors.muted }}>
                            Upload one or more images.
                          </div>
                        </div>
                      )}
                      {items.map((item) => (
                        <div key={item.id} className="col-12 col-sm-6">
                          <div className="p-2 rounded-3" style={{ border: `1px solid ${colors.border}`, background: colors.cardBg }}>
                            <img src={item.previewUrl} alt={item.name} className="img-fluid rounded w-100 mb-2" style={{ height: 120, objectFit: "cover" }} />
                            <div className="small fw-semibold text-truncate">{item.name}</div>
                            <div className="small" style={{ color: colors.muted }}>{item.sizeKB} KB</div>
                            <button className="btn btn-sm w-100 mt-2" style={ui.buttonMutedDanger} onClick={() => removeItem(item.id)}>
                              Remove
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="col-12 col-lg-6">
                  <div className="p-3 rounded-3 h-100" style={{ background: colors.cardSoft, border: `1px solid ${colors.border}` }}>
                    <div className="d-flex justify-content-between align-items-center mb-3">
                      <h6 className="mb-0 fw-bold" style={{ color: colors.text }}>Output</h6>
                      <small style={{ color: colors.muted }}>{mode === "browser" ? "Browser" : "Backend"}</small>
                    </div>
                    <div className="d-flex flex-wrap gap-2 mb-3">
                      <button
                        className="btn"
                        style={mode === "browser" ? ui.buttonPrimarySoft : ui.buttonGhost}
                        onClick={() => setMode("browser")}
                      >
                        Browser
                      </button>
                      <button
                        className="btn"
                        style={mode === "backend" ? ui.buttonAccentSoft : ui.buttonGhost}
                        onClick={() => setMode("backend")}
                      >
                        Backend
                      </button>
                    </div>
                    <div className="mb-3">
                      <div className="d-flex justify-content-between">
                        <label className="form-label fw-semibold mb-0" style={{ color: colors.text }}>Quality ({quality}%)</label>
                        <small style={{ color: colors.muted }}>10-100</small>
                      </div>
                      <input
                        type="range"
                        className="form-range"
                        min={10}
                        max={100}
                        value={quality}
                        onChange={(e) => setQuality(Number(e.target.value))}
                      />
                    </div>
                    <div className="d-flex flex-wrap gap-2 mb-3">
                      <button className="btn fw-semibold" style={ui.buttonSuccessSoft} onClick={handleConvertAll} disabled={loading}>
                        {loading ? "Converting..." : "Convert All"}
                      </button>
                      <button className="btn" style={ui.buttonGhost} onClick={downloadAllConverted}>
                        Save All
                      </button>
                    </div>
                    <div className="row g-2">
                      {items.map((item) => (
                        <div key={`out-${item.id}`} className="col-12">
                          <div className="p-2 rounded-3 d-flex justify-content-between align-items-center" style={{ border: `1px solid ${colors.border}`, background: colors.cardBg }}>
                            <div className="small">
                              <div className="fw-semibold text-truncate">{item.convertedName || item.name}</div>
                              <div style={{ color: item.status === "error" ? "#ef4444" : colors.muted }}>
                                {item.status === "done"
                                  ? `Ready ${item.convertedSizeKB ? `(${item.convertedSizeKB} KB)` : ""}`
                                  : item.status === "processing"
                                  ? "Processing"
                                  : item.error || "Pending"}
                              </div>
                            </div>
                            <button
                              className="btn btn-sm"
                              style={ui.buttonSuccessSoft}
                              disabled={!item.convertedUrl}
                              onClick={() => downloadSingle(item)}
                            >
                              Save
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}